};

// Para no arrastrar texto completo de paginas que no son finalistas
const resumenPaginas = paginas.map(({ texto, ...resto }) => resto);

return [{ json: { ...p, paginas: resumenPaginas, finalistas, estadisticas_lectura: estadisticas } }];

