].forEach((t, i) => L.push(`${i + 1}. ${t}`));
L.push('');
L.push('Quedamos atentos a su respuesta.');
L.push('');
if (cands.length) {
  L.push('Preguntas adicionales por proveedor, segun lo que no se pudo verificar:');
  cands.slice(0, 5).forEach((c) => {
    const f = [];
